// tb.v: random-stimulus testbench for Types, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg clk = 1'b0;
    reg rst = 1'b0;
    reg [23:0] px = 24'd0;
    reg [1:0] idx = 2'd0;
    reg [7:0] val = 8'd0;
    reg [49:0] cmd = 50'd0;
    wire [9:0] grey;
    wire [1:0] kind_out;
    wire is_write;
    wire [15:0] addr;
    wire [7:0] elem;
    wire [7:0] green1;
    wire [41:0] obj_out;
    reg [83:0] stim [0:239];
    integer i;

    Types dut (
        .clk(clk),
        .rst(rst),
        .px(px),
        .idx(idx),
        .val(val),
        .cmd(cmd),
        .grey(grey),
        .kind_out(kind_out),
        .is_write(is_write),
        .addr(addr),
        .elem(elem),
        .green1(green1),
        .obj_out(obj_out)
    );

    task cycle_clk;
        begin
            clk = 1'b1;
            #5;
            clk = 1'b0;
            #5;
        end
    endtask

    task do_reset;
        begin
            rst = 1'b1;
            #1;
            cycle_clk;
            cycle_clk;
            rst = 1'b0;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {px, idx, val, cmd} = stim[i];
            #1;
            $display("D %0d %h %h %h %h %h %h %h", i, grey, kind_out, is_write, addr, elem, green1, obj_out);
            cycle_clk;
        end
        $finish;
    end
endmodule
